36	#include "tensorflow/core/platform/thread_annotations.h"
37	#include "tensorflow/core/platform/types.h"
38	
39	namespace tensorflow {
40	
41	// Users that want to look up an OpDef by type name should take an
42	// OpRegistryInterface.  Functions accepting a
43	// (const) OpRegistryInterface* may call LookUp() from multiple threads.
44	class OpRegistryInterface {
45	 public:
46	  virtual ~OpRegistryInterface() = default;
47	
48	  // Returns an error status and sets *op_reg_data to nullptr if no OpDef is
49	  // registered under that name, otherwise returns the registered OpDef.
50	  // Caller must not delete the returned pointer.
51	  virtual absl::Status LookUp(const std::string& op_type_name,
52	                              const OpRegistrationData** op_reg_data) const = 0;
53	
54	  // Shorthand for calling LookUp to get the OpDef.
55	  absl::Status LookUpOpDef(const std::string& op_type_name,
56	                           const OpDef** op_def) const;
57	};
58	
59	// The standard implementation of OpRegistryInterface, along with a
60	// global singleton used for registering ops via the REGISTER
61	// macros below.  Thread-safe.
62	//
63	// Example registration:
64	//   OpRegistry::Global()->Register(
65	//     [](OpRegistrationData* op_reg_data)->Status {
66	//       // Populate *op_reg_data here.
67	//       return OkStatus();
68	//   });
69	class OpRegistry : public OpRegistryInterface {
70	 public:
71	  typedef std::function<absl::Status(OpRegistrationData*)>
72	      OpRegistrationDataFactory;
73	
74	  OpRegistry();
75	
76	  void Register(const OpRegistrationDataFactory& op_data_factory);
77	
78	  absl::Status LookUp(const std::string& op_type_name,
79	                      const OpRegistrationData** op_reg_data) const override;
80	
81	  // Returns OpRegistrationData* of registered op type, else returns nullptr.
82	  const OpRegistrationData* LookUp(const std::string& op_type_name) const;
83	
84	  // Fills *ops with all registered OpDefs (except those with names
85	  // starting with '_' if include_internal == false) sorted in
86	  // ascending alphabetical order.
87	  void Export(bool include_internal, OpList* ops) const;
88	
89	  // Returns ASCII-format OpList for all registered OpDefs (except
90	  // those with names starting with '_' if include_internal == false).
91	  std::string DebugString(bool include_internal) const;
92	
93	  // A singleton available at startup.
94	  static OpRegistry* Global();
95	
96	  // Get all registered ops.
97	  void GetRegisteredOps(std::vector<OpDef>* op_defs);
98	
99	  // Get all `OpRegistrationData`s.
100	  void GetOpRegistrationData(std::vector<OpRegistrationData>* op_data);
101	
102	  // Registers a function that validates op registry.
103	  void RegisterValidator(
104	      std::function<absl::Status(const OpRegistryInterface&)> validator) {
105	    op_registry_validator_ = std::move(validator);
106	  }
107	
108	  // Watcher, a function object.
109	  // The watcher, if set by SetWatcher(), is called every time an op is
110	  // registered via the Register function. The watcher is passed the Status
111	  // obtained from building and adding the OpDef to the registry, and the OpDef
112	  // itself if it was successfully built. A watcher returns a Status which is in
113	  // turn returned as the final registration status.
114	  typedef std::function<absl::Status(const absl::Status&, const OpDef&)>
115	      Watcher;
116	
117	  // An OpRegistry object has only one watcher. This interface is not thread
118	  // safe, as different clients are free to set the watcher any time.
119	  // Clients are expected to atomically perform the following sequence of
120	  // operations :
121	  // SetWatcher(a_watcher);
122	  // Register some ops;
123	  // op_registry->ProcessRegistrations();
124	  // SetWatcher(nullptr);
125	  // Returns a non-OK status if a non-null watcher is over-written by another
126	  // non-null watcher.
127	  absl::Status SetWatcher(const Watcher& watcher);
128	
129	  // Process the current list of deferred registrations. Note that calls to
130	  // Export, LookUp and DebugString would also implicitly process the deferred
131	  // registrations. Returns the status of the first failed op registration or
132	  // OkStatus() otherwise.
133	  absl::Status ProcessRegistrations() const;
134	
135	  // Defer the registrations until a later call to a function that processes
136	  // deferred registrations are made. Normally, registrations that happen after
137	  // calls to Export, LookUp, ProcessRegistrations and DebugString are processed
138	  // immediately. Call this to defer future registrations.
139	  void DeferRegistrations();
140	
141	  // Clear the registrations that have been deferred.
142	  void ClearDeferredRegistrations();
143	
144	 private:
145	  // Ensures that all the functions in deferred_ get called, their OpDef's
146	  // registered, and returns with deferred_ empty.  Returns true the first
147	  // time it is called. Prints a fatal log if any op registration fails.
148	  bool MustCallDeferred() const TF_EXCLUSIVE_LOCKS_REQUIRED(mu_);
149	
150	  // Calls the functions in deferred_ and registers their OpDef's
151	  // It returns the Status of the first failed op registration or OkStatus()
152	  // otherwise.
153	  absl::Status CallDeferred() const TF_EXCLUSIVE_LOCKS_REQUIRED(mu_);
154	
155	  // Add 'def' to the registry with additional data 'data'. On failure, or if
156	  // there is already an OpDef with that name registered, returns a non-okay
157	  // status.
158	  absl::Status RegisterAlreadyLocked(
159	      const OpRegistrationDataFactory& op_data_factory) const
160	      TF_EXCLUSIVE_LOCKS_REQUIRED(mu_);
161	
162	  const OpRegistrationData* LookUpSlow(const std::string& op_type_name) const;
163	
164	  mutable mutex mu_;
165	  // Functions in deferred_ may only be called with mu_ held.
166	  mutable std::vector<OpRegistrationDataFactory> deferred_ TF_GUARDED_BY(mu_);
167	  // Values are owned.
168	  mutable absl::flat_hash_map<std::string,
169	                              std::unique_ptr<const OpRegistrationData>>
170	      registry_ TF_GUARDED_BY(mu_);
171	  mutable bool initialized_ TF_GUARDED_BY(mu_);
172	
173	  // Registry watcher.
174	  mutable Watcher watcher_ TF_GUARDED_BY(mu_);
175	
176	  std::function<absl::Status(const OpRegistryInterface&)>
177	      op_registry_validator_;
178	};
179	
180	// An adapter to allow an OpList to be used as an OpRegistryInterface.
181	//
182	// Note that shape inference functions are not passed in to OpListOpRegistry, so
183	// it will return an unusable shape inference function for every op it supports;
184	// therefore, it should only be used in contexts where this is okay.
185	class OpListOpRegistry : public OpRegistryInterface {
186	 public:
187	  // Does not take ownership of op_list, *op_list must outlive *this.
188	  explicit OpListOpRegistry(const OpList* op_list);
189	  absl::Status LookUp(const std::string& op_type_name,
190	                      const OpRegistrationData** op_reg_data) const override;
191	
192	  // Returns OpRegistrationData* of op type in list, else returns nullptr.
193	  const OpRegistrationData* LookUp(const std::string& op_type_name) const;
194	
195	 private:
196	  // Values are owned.
197	  absl::flat_hash_map<std::string, std::unique_ptr<const OpRegistrationData>>
198	      index_;
199	};
200	
201	// Support for defining the OpDef (specifying the semantics of the Op and how
202	// it should be created) and registering it in the OpRegistry::Global()
203	// registry.  Usage:
204	//
205	// REGISTER_OP("my_op_name")
206	//     .Attr("<name>:<type>")
207	//     .Attr("<name>:<type>=<default>")
208	//     .Input("<name>:<type-expr>")
209	//     .Input("<name>:Ref(<type-expr>)")
210	//     .Output("<name>:<type-expr>")
211	//     .Doc(R"(
212	// <1-line summary>
213	// <rest of the description (potentially many lines)>
214	// <name-of-attr-input-or-output>: <description of name>
215	// <name-of-attr-input-or-output>: <description of name;
216	//   if long, indent the description on subsequent lines>
217	// )");
218	//
219	// Note: .Doc() should be last.
220	// For details, see the OpDefBuilder class in op_def_builder.h.
221	
222	namespace register_op {
223	
224	class OpDefBuilderWrapper {
225	 public:
226	  explicit OpDefBuilderWrapper(const char name[]) : builder_(name) {}
227	  OpDefBuilderWrapper& Attr(std::string spec) {
228	    builder_.Attr(std::move(spec));
229	    return *this;
230	  }
231	  OpDefBuilderWrapper& Attr(const char* spec) TF_ATTRIBUTE_NOINLINE {
232	    return Attr(std::string(spec));
233	  }
234	  OpDefBuilderWrapper& Input(std::string spec) {
235	    builder_.Input(std::move(spec));
236	    return *this;
237	  }
238	  OpDefBuilderWrapper& Input(const char* spec) TF_ATTRIBUTE_NOINLINE {
239	    return Input(std::string(spec));
240	  }
241	  OpDefBuilderWrapper& Output(std::string spec) {
242	    builder_.Output(std::move(spec));
243	    return *this;
244	  }
245	  OpDefBuilderWrapper& Output(const char* spec) TF_ATTRIBUTE_NOINLINE {
246	    return Output(std::string(spec));
247	  }
248	  OpDefBuilderWrapper& SetIsCommutative() {
249	    builder_.SetIsCommutative();
250	    return *this;
251	  }
252	  OpDefBuilderWrapper& SetIsAggregate() {
253	    builder_.SetIsAggregate();
254	    return *this;
255	  }
256	  OpDefBuilderWrapper& SetIsStateful() {
257	    builder_.SetIsStateful();
258	    return *this;
259	  }
260	  OpDefBuilderWrapper& SetDoNotOptimize() {
261	    // We don't have a separate flag to disable optimizations such as constant
262	    // folding and CSE so we reuse the stateful flag.
263	    builder_.SetIsStateful();
264	    return *this;
265	  }
266	  OpDefBuilderWrapper& SetAllowsUninitializedInput() {
267	    builder_.SetAllowsUninitializedInput();
268	    return *this;
269	  }
270	  OpDefBuilderWrapper& Deprecated(int version, std::string explanation) {
271	    builder_.Deprecated(version, std::move(explanation));
272	    return *this;
273	  }
274	  OpDefBuilderWrapper& Doc(std::string text) {
275	    builder_.Doc(std::move(text));
276	    return *this;
277	  }
278	  OpDefBuilderWrapper& SetShapeFn(OpShapeInferenceFn fn) {
279	    builder_.SetShapeFn(std::move(fn));
280	    return *this;
281	  }
282	  OpDefBuilderWrapper& SetIsDistributedCommunication() {
283	    builder_.SetIsDistributedCommunication();
284	    return *this;
285	  }
286	
287	  OpDefBuilderWrapper& SetTypeConstructor(OpTypeConstructor fn) {
288	    builder_.SetTypeConstructor(std::move(fn));
289	    return *this;
290	  }
291	
292	  OpDefBuilderWrapper& SetForwardTypeFn(TypeInferenceFn fn) {
293	    builder_.SetForwardTypeFn(std::move(fn));
294	    return *this;
295	  }
296	
297	  OpDefBuilderWrapper& SetReverseTypeFn(int input_number, TypeInferenceFn fn) {
298	    builder_.SetReverseTypeFn(input_number, std::move(fn));
299	    return *this;
300	  }
301	
302	  const ::tensorflow::OpDefBuilder& builder() const { return builder_; }
303	
304	  InitOnStartupMarker operator()();
305	
306	 private:
307	  mutable ::tensorflow::OpDefBuilder builder_;
308	};
309	
310	}  // namespace register_op
311	
312	#define REGISTER_OP_IMPL(ctr, name, is_system_op)                         \
313	  static ::tensorflow::InitOnStartupMarker const register_op##ctr         \
314	      TF_ATTRIBUTE_UNUSED =                                               \
315	          TF_INIT_ON_STARTUP_IF(is_system_op || SHOULD_REGISTER_OP(name)) \
316	          << ::tensorflow::register_op::OpDefBuilderWrapper(name)
317	
318	#define REGISTER_OP(name)        \
319	  TF_ATTRIBUTE_ANNOTATE("tf:op") \
320	  TF_NEW_ID_FOR_INIT(REGISTER_OP_IMPL, name, false)
321	
322	// The `REGISTER_SYSTEM_OP()` macro acts as `REGISTER_OP()` except
323	// that the op is registered unconditionally even when selective
324	// registration is used.
325	#define REGISTER_SYSTEM_OP(name)        \
326	  TF_ATTRIBUTE_ANNOTATE("tf:op")        \
327	  TF_ATTRIBUTE_ANNOTATE("tf:op:system") \
328	  TF_NEW_ID_FOR_INIT(REGISTER_OP_IMPL, name, true)
329	
330	}  // namespace tensorflow
331	
332	#endif  // TENSORFLOW_CORE_FRAMEWORK_OP_H_
